INSERT IGNORE INTO substitute_assignments (schedule_entry_id, original_teacher_id, substitute_teacher_id, absence_date, reason, status) SELECT e.id, e.teacher_id, (SELECT id FROM teachers WHERE employee_no = 'BCP-F-1012'), '2026-10-06', 'Attending the DICT cybersecurity summit', 'Assigned' FROM schedule_entries e JOIN sections sec ON sec.id = e.section_id JOIN subjects sub ON sub.id = e.subject_id WHERE sec.code = 'BSIT-3A' AND sec.academic_year = '2026-2027' AND sec.semester = '1st Semester' AND sub.code = 'IT301' AND e.status = 'Published' ORDER BY e.id LIMIT 1;
